def summarize(tickets):
    """Return open-ticket counts grouped by exact team name."""
    open_counts = {}

    for ticket in tickets:
        if ticket["closed_at"] is None:
            team = ticket["team"]
            open_counts[team] = open_counts.get(team, 0) + 1

    return [
        {"team": team, "open_count": open_counts[team]}
        for team in sorted(open_counts)
    ]

